import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Plan — from a hand-tuned kernel to a substrate-native search","description":"","frontmatter":{"title":"Plan — from a hand-tuned kernel to a substrate-native search","type":"report","date":"2026-10-27T00:00:00.000Z"},"headers":[],"relativePath":"graphopt/project/reports/2026-10-27-plan-roofline-to-search.md","filePath":"vendored/graphopt/project/reports/2026-10-27-plan-roofline-to-search.md"}`),a={name:`graphopt/project/reports/2026-10-27-plan-roofline-to-search.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="plan-—-from-a-hand-tuned-kernel-to-a-substrate-native-search" tabindex="-1">Plan — from a hand-tuned kernel to a substrate-native search <a class="header-anchor" href="#plan-—-from-a-hand-tuned-kernel-to-a-substrate-native-search" aria-label="Permalink to “Plan — from a hand-tuned kernel to a substrate-native search”">​</a></h1><p><strong>Date:</strong> 2026-10-27 <strong>Follows:</strong> <code>2026-10-27-automatic-tuning-margin.md</code><strong>State:</strong> a hand-written int4 GEMV beats <code>awq_gemm</code> 3.32× on <code>down_proj</code>, runs at 44 % of the measured 89 GB/s roofline, and does not make the model faster end-to-end.</p><h2 id="the-four-things-blocking-a-real-result" tabindex="-1">The four things blocking a real result <a class="header-anchor" href="#the-four-things-blocking-a-real-result" aria-label="Permalink to “The four things blocking a real result”">​</a></h2><ol><li><strong>Kernel efficiency</strong> — 8× redundant packed-word loads, 32-bit loads where int4 wants 128-bit, fp32 output where fp16 halves the traffic, split-k atomics adding traffic back. Roofline says 24.6 µs; we run 55.9 µs.</li><li><strong>Model-level dilution</strong> — fp32↔fp16 conversion per call plus only two of four geometries routed to us. End-to-end is +1.0 % (flat).</li><li><strong>No vocabulary for quantized ops</strong> — the minting loop cannot propose a packed-int4 kernel because &quot;load nibble / dequantize&quot; is not a thing it can say.</li><li><strong>No template space</strong> — the loop tunes configs, not structure (GEMV vs tiled vs split-k), because structure lives in my head.</li></ol><h2 id="phases-and-gates" tabindex="-1">Phases and gates <a class="header-anchor" href="#phases-and-gates" aria-label="Permalink to “Phases and gates”">​</a></h2><table tabindex="0"><thead><tr><th>phase</th><th>work</th><th>gate</th><th>kill</th></tr></thead><tbody><tr><td><strong>1. Close the gap by hand</strong></td><td>load-once/unpack-8, 128-bit loads, fp16 in/out with fp32 accumulate, split-k only where K is large</td><td><code>down_proj</code> &lt; 35 µs (≥70 % of roofline), <code>q_proj</code> &lt; 20 µs, exact to 1e-3 (fp16)</td><td>hand-tuning cannot reach 70 % of roofline → the whole thread is dead</td></tr><tr><td><strong>2. End-to-end, dtype-clean</strong></td><td>rerun the routed AWQ test with the fp16 kernel</td><td>model ≥ 3 % faster, paired, locked clocks, tokens identical</td><td>flat → the product is a fast-op library for unattended shapes, not serving</td></tr><tr><td><strong>3. Make it searchable</strong></td><td>int4 as vocabulary; template space (GEMV / tiled / split-k × load width × tiles × dtype) scored by the calibrated roofline</td><td>the machine <strong>rediscovers the phase-1 kernel without being told its structure</strong></td><td>the search cannot beat a trivial baseline → the loop is not yet a kernel designer</td></tr><tr><td><strong>4. Coverage</strong></td><td>sweep shapes, models, formats; emit the routing table automatically</td><td>a routing table produced with no hand-written entries</td><td>—</td></tr></tbody></table><h2 id="methodology-non-negotiable" tabindex="-1">Methodology (non-negotiable) <a class="header-anchor" href="#methodology-non-negotiable" aria-label="Permalink to “Methodology (non-negotiable)”">​</a></h2><ul><li><strong>Paired measurement</strong> in one process, alternating order each round — sequential comparison produced three different answers (+8 %, +6.5 %, −1.8 %) for the same two models.</li><li><strong>Locked clocks, reported spread.</strong> Median + sd + win count. No best-of, no warmup asymmetry.</li><li><strong>Exactness before speed.</strong> <code>max|Δ|</code> against the reference, measured before any timer runs; a precision change is reported as such, never folded into a speed claim.</li><li><strong>Roofline first.</strong> Bytes ÷ measured bandwidth before building, and every result reported as a fraction of that ceiling.</li><li><strong>Kill criteria decided before running</strong>, as in the table above.</li><li><strong>Configs by sweep, not taste</strong> — and record which config won.</li><li><strong>Negatives kept next to wins.</strong> Corrections appended, never silently edited.</li></ul><h2 id="architecture-requirements-the-part-the-prototype-fails" tabindex="-1">Architecture requirements (the part the prototype fails) <a class="header-anchor" href="#architecture-requirements-the-part-the-prototype-fails" aria-label="Permalink to “Architecture requirements (the part the prototype fails)”">​</a></h2><p>The current kernel is a <strong>prototype that proves the physics</strong>, not a component. To be worth keeping it must become:</p><ul><li><strong>substrate-native</strong> — expressed as ops the kernel domain already knows (<code>KERNEL_RULES</code>, <code>KernelSink</code>, the cost model), so the mint, the sieve and the certificate apply to it;</li><li><strong>composable</strong> — a template instantiated by parameters, not one monolithic kernel per shape;</li><li><strong>decoupled</strong> — no monkeypatched vLLM internals in the shipped path; an op plus a routing policy that any host can call;</li><li><strong>reusable and scalable</strong> — one search harness over many shapes and formats, with the routing table emitted, not typed.</li></ul><p>Phase 3 is where the prototype becomes a component. Anything shipped before that is a demo and should be labelled as one.</p><h2 id="risks" tabindex="-1">Risks <a class="header-anchor" href="#risks" aria-label="Permalink to “Risks”">​</a></h2><ul><li><strong>Phase 2 flat.</strong> Cheapest thing to learn, do it first.</li><li><strong>Referee noise at scale.</strong> ±50 % drift was observed on this box; a search over thousands of candidates measured that way produces confident nonsense. Lock clocks, repeat, and gate on the referee before trusting the search.</li><li><strong>Overfitting to one GPU.</strong> Every number here is a 4 GB laptop card; the roofline model must be calibrated per machine (<code>scripts/calibrate_profile.py</code>) before any routing table ships.</li></ul>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};